// Replicates jsonschema.exceptions.ErrorTree closely enough for the reference
// program, which only reads `total_errors`. The tree is still built from the
// error instance paths, like the original.
export class ErrorTree {
  constructor(errors = []) {
    // Errors placed directly at this node.
    this.errors = [];
    // Child trees keyed by path element (property name or array index).
    this._contents = new Map();

    for (const error of errors) {
      let container = this;
      for (const element of error.path ?? []) {
        if (!container._contents.has(element)) {
          container._contents.set(element, new ErrorTree());
        }
        container = container._contents.get(element);
      }
      container.errors.push(error);
    }
  }

  get total_errors() {
    let total = this.errors.length;
    for (const child of this._contents.values()) {
      total += child.total_errors;
    }
    return total;
  }
}

