// Replicates the reference program's argparse behavior:
//   parser.add_argument("--a", required=True, help="instance (JSON string)")
//   parser.add_argument("--b", required=True, help="schema (JSON string)")
//
// - Supports "--a value", "--a=value", and unambiguous prefix abbreviations
//   ("--he" -> "--help"), like Python argparse with allow_abbrev=True.
// - "-h"/"--help" prints help to stdout and exits 0.
// - "--" ends option parsing; the rest are positionals.
// - Missing required options or unrecognized arguments print a usage/error
//   message to stderr and exit 2 (stdout stays empty).
// - A required-option error takes precedence over unrecognized arguments,
//   matching argparse (the required check happens in parse_known_args).

const PROG = 'test20_executable';
const USAGE = `usage: ${PROG} [-h] --a A --b B`;
const HELP = `${USAGE}

options:
  -h, --help  show this help message and exit
  --a A       instance (JSON string)
  --b B       schema (JSON string)
`;

// Python argparse._negative_number_matcher.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const LONG_OPTIONS = ['--help', '--a', '--b'];

function fail(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit() {
  process.stdout.write(HELP + '\n');
  process.exit(0);
}

// Whether the token following an option should be consumed as its value,
// mirroring argparse._parse_optional / _get_values.
function looksLikeValue(token) {
  if (!token.startsWith('-')) return true;
  if (token === '-') return true;
  if (NEGATIVE_NUMBER.test(token)) return true;
  if (token.includes(' ')) return true;
  return false;
}

function resolveLongOption(name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const matches = LONG_OPTIONS.filter((option) => option.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    fail(`ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv) {
  const values = {};
  const extras = [];
  let optionsEnded = false;

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];

    if (optionsEnded) {
      extras.push(arg);
      i += 1;
      continue;
    }

    if (arg === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }

    if (arg.startsWith('--')) {
      const eqIndex = arg.indexOf('=');
      const name = eqIndex === -1 ? arg : arg.slice(0, eqIndex);
      const inlineValue = eqIndex === -1 ? null : arg.slice(eqIndex + 1);
      const option = resolveLongOption(name);

      if (option === null) {
        extras.push(arg);
        i += 1;
        continue;
      }
      if (option === '--help') {
        printHelpAndExit();
      }
      // --a / --b both require a value.
      if (inlineValue !== null) {
        values[option] = inlineValue;
        i += 1;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || !looksLikeValue(next)) {
        fail(`argument ${option}: expected one argument`);
      }
      values[option] = next;
      i += 2;
      continue;
    }

    if (arg.startsWith('-') && arg !== '-' && !NEGATIVE_NUMBER.test(arg)) {
      if (arg === '-h') {
        printHelpAndExit();
      }
      extras.push(arg);
      i += 1;
      continue;
    }

    // Positional argument: not accepted by this parser.
    extras.push(arg);
    i += 1;
  }

  const missing = ['--a', '--b'].filter((option) => !(option in values));
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values['--a'], b: values['--b'] };
}

