// Reimplements the reference Python program (test20.py) in pure Node.js ESM.
//
// It validates a JSON instance against a JSON schema with all five draft
// validator classes and prints 20 lines, in this exact order:
//   1-5:   is_valid for draft4, draft6, draft7, 2019-09, 2020-12
//   6-10:  len(list(iter_errors(...))) for the same drafts
//   11-15: check_schema(...) results (always None on success)
//   16:    ErrorTree(draft7 errors).total_errors
//   17:    len(FormatChecker().checkers)
//   18:    validators.validator_for(schema).__name__
//   19:    draft7_validator.evolve(schema=schema).is_valid(instance)
//   20:    whether line 3 == line 19
//
// Like the Python program, every result is computed before anything is
// printed: any exception (JSON parse failure, invalid schema, unknown type,
// boolean root schema, ...) means nothing is written to stdout and the
// process exits non-zero.

import {
  Draft4Validator,
  Draft6Validator,
  Draft7Validator,
  Draft201909Validator,
  Draft202012Validator,
} from './lib/drafts.mjs';
import { ErrorTree } from './lib/errortree.mjs';
import { FORMAT_CHECKER_COUNT } from './lib/formats.mjs';
import { validatorForName } from './lib/validatorFor.mjs';
import { parseArgs } from './lib/argparse.mjs';

// Python str() formatting for the values we print.
function pyStr(value) {
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value === null || value === undefined) return 'None';
  return String(value);
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  try {
    const instance = JSON.parse(args.a);
    const schema = JSON.parse(args.b);

    const validators = [
      new Draft4Validator(schema),
      new Draft6Validator(schema),
      new Draft7Validator(schema),
      new Draft201909Validator(schema),
      new Draft202012Validator(schema),
    ];

    // Same computation order as the Python program: all is_valid calls,
    // then all iter_errors counts, then all check_schema calls.
    const valids = validators.map((validator) => validator.isValid(instance));
    const errorLists = validators.map((validator) => validator.iterErrors(instance));
    const checks = validators.map((validator) => validator.checkSchema(schema));

    const draft7 = validators[2];
    const errorTree = new ErrorTree(errorLists[2]);
    const validatorName = validatorForName(schema);
    const evolved = draft7.evolve({ schema });
    const evolvedValid = evolved.isValid(instance);

    const lines = [
      ...valids.map(pyStr),
      ...errorLists.map((errors) => String(errors.length)),
      ...checks.map(pyStr),
      String(errorTree.total_errors),
      String(FORMAT_CHECKER_COUNT),
      validatorName,
      pyStr(evolvedValid),
      pyStr(valids[2] === evolvedValid),
    ];

    process.stdout.write(lines.join('\n') + '\n');
  } catch {
    // Mirror the Python program crashing: nothing on stdout, non-zero exit.
    process.exit(1);
  }
}

main();

