import { createValidatorClass } from '/output/lib/engine.mjs';
import { makeError } from '/output/lib/errors.mjs';

// --- stub keyword fns (mimic contract behavior) ---
const typeFn = (ctx, value, instance) => {
  const ok = (t) => {
    switch (t) {
      case 'integer': return typeof instance === 'number' && Number.isInteger(instance);
      case 'number': return typeof instance === 'number';
      case 'string': return typeof instance === 'string';
      case 'object': return typeof instance === 'object' && instance !== null && !Array.isArray(instance);
      case 'array': return Array.isArray(instance);
      case 'boolean': return typeof instance === 'boolean';
      case 'null': return instance === null;
      default: throw new Error('UnknownType: ' + t);
    }
  };
  const types = Array.isArray(value) ? value : [value];
  return types.some(ok) ? [] : [makeError()];
};
const propertiesFn = (ctx, value, instance) => {
  if (typeof instance !== 'object' || instance === null || Array.isArray(instance)) return [];
  const errs = [];
  for (const [k, sub] of Object.entries(value)) {
    if (k in instance) errs.push(...ctx.descend(instance[k], sub, [k], ['properties', k]));
  }
  return errs;
};
const itemsFn = (ctx, value, instance) => {
  if (!Array.isArray(instance)) return [];
  const errs = [];
  instance.forEach((el, i) => errs.push(...ctx.descend(el, value, [i], ['items'])));
  return errs;
};
const minItemsFn = (ctx, value, instance) =>
  Array.isArray(instance) && instance.length < value ? [makeError()] : [];

const kw = { type: typeFn, properties: propertiesFn, items: itemsFn, minItems: minItemsFn };

// mini meta: root type object, properties values are schemas ($ref #)
const miniMeta = {
  id: 'http://example.com/mini#',
  type: 'object',
  properties: {
    properties: { type: 'object', additionalProperties: { $ref: '#' } },
    items: { $ref: '#' },
  },
};
const additionalPropertiesFn = (ctx, value, instance) => {
  if (typeof instance !== 'object' || instance === null || Array.isArray(instance)) return [];
  const errs = [];
  const props = ctx && instance; // simplified: all keys extra (no properties tracking in stub)
  for (const k of Object.keys(instance)) errs.push(...ctx.descend(instance[k], value, [k], ['additionalProperties']));
  return errs;
};
const metaKw = { ...kw, additionalProperties: additionalPropertiesFn };

const mk = (draft) => createValidatorClass({ name: 'V' + draft, draft, keywords: draft === 'meta' ? metaKw : kw, metaSchema: miniMeta });
const [V4, V6, V7, V19, V20] = [4, 6, 7, 2019, 2020].map(mk);

let pass = 0, fail = 0;
function eq(actual, expected, label) {
  const a = JSON.stringify(actual), e = JSON.stringify(expected);
  if (a === e) { pass++; } else { fail++; console.log(`FAIL ${label}: got ${a} want ${e}`); }
}

// 1. $ref with sibling type — legacy short-circuits, modern evaluates both
const s1 = { $ref: '#/definitions/n', type: 'integer', definitions: { n: { type: 'number' } } };
eq([V4, V6, V7, V19, V20].map(V => new V(s1).iterErrors('x').length), [1, 1, 1, 2, 2], '$ref+sibling counts');
eq([V4, V6, V7, V19, V20].map(V => new V(s1).isValid('x')), [false, false, false, false, false], '$ref+sibling valid');

// 2. $defs ref, all drafts
const s2 = { $ref: '#/$defs/n', $defs: { n: { type: 'number' } } };
eq([V4, V6, V7, V19, V20].map(V => new V(s2).iterErrors('x').length), [1, 1, 1, 1, 1], '$defs counts');
eq([V4, V6, V7, V19, V20].map(V => new V(s2).iterErrors(3).length), [0, 0, 0, 0, 0], '$defs valid');

// 3. recursive ref to root, terminating
const s3 = { items: { $ref: '#' }, minItems: 1 };
eq(new V7(s3).iterErrors([1, 2]).length, 0, 'recursive ref valid');
eq(new V7(s3).iterErrors([[1], []]).length, 1, 'recursive ref nested (minItems fails on [])');

// 4. boolean subschema
const s4 = { properties: { a: false } };
eq([V4, V6, V7, V19, V20].map(V => new V(s4).iterErrors({ a: 1 }).length), [1, 1, 1, 1, 1], 'false subschema');
const s4b = { properties: { a: true } };
eq(new V20(s4b).iterErrors({ a: 1 }).length, 0, 'true subschema');

// 5. self ref -> throws
try { new V7({ $ref: '#' }).isValid(1); eq('no-throw', 'throw', 'self-ref'); } catch { pass++; }

// 6. missing ref -> throws
try { new V7({ $ref: '#/definitions/missing' }).isValid(1); eq('no-throw', 'throw', 'missing ref'); } catch { pass++; }

// 7. boolean root -> constructor throws
for (const V of [V4, V6, V7, V19, V20]) {
  try { new V(true); eq('no-throw', 'throw', 'bool root'); } catch { pass++; }
}

// 8. evolve
const v7 = new V7({ type: 'integer' });
const ev = v7.evolve({ schema: { type: 'string' } });
eq([ev instanceof V7, ev.isValid('x'), ev.isValid(1), v7.isValid(1)], [true, true, false, true], 'evolve');

// 9. ctx.isValid and ctx.validator
eq(typeof v7.isValid, 'function', 'api surface');
{
  const kwX = { type: typeFn, not: (ctx, val, inst) => ctx.isValid(inst, val) ? [makeError()] : [] };
  const VX = createValidatorClass({ name: 'VX', draft: 7, keywords: kwX, metaSchema: miniMeta });
  eq(new VX({ not: { type: 'string' } }).iterErrors('x').length, 1, 'ctx.isValid via not');
  eq(new VX({ not: { type: 'string' } }).iterErrors(5).length, 0, 'ctx.isValid via not 2');
}

// 10. checkSchema: valid -> null; boolean subschema under properties -> throw (draft4-like)
eq(new V7({ type: 'integer' }).checkSchema({ type: 'integer' }), null, 'checkSchema valid');
try {
  new V7({ properties: { a: false } }).checkSchema({ properties: { a: false } });
  eq('no-throw', 'throw', 'checkSchema false subschema');
} catch { pass++; }

// 11. descend paths threaded
{
  const errs = new V7({ properties: { a: false } }).iterErrors({ a: 1 });
  eq([errs[0].path, errs[0].schemaPath], [['a'], ['properties', 'a']], 'error paths');
}

// 12. unknown keyword ignored
eq(new V7({ bogusKw: 5 }).iterErrors(1).length, 0, 'unknown keyword ignored');

// 13. unknown type name throws
try { new V7({ type: 'bogus' }).isValid(1); eq('no-throw', 'throw', 'unknown type'); } catch { pass++; }

console.log(`pass=${pass} fail=${fail}`);
process.exit(fail ? 1 : 0);

