// Scratch test: compare argparse behavior (stdout/stderr/exit) against executable.
import { spawnSync } from 'node:child_process';

const cases = [
  ['--a', '{"a":1}', '--b', '{"type":"object"}'],
  ['--a={"a":1}', '--b={"type":"object"}'],
  ['--b', '{}', '--a', '1'],
  ['--a', '{"a":1}'],
  ['--b', '{}'],
  [],
  ['--a', '1', '--b', '{}', '--c', 'foo'],
  ['--a', '1', '--b', '{}', 'extra'],
  ['--a', '1', '--b', '{}', 'e1', 'e2'],
  ['--a', 'x', 'junk'],
  ['--a'],
  ['--a', '--b', 'x'],
  ['--he'],
  ['-h'],
  ['--h'],
  ['--help'],
  ['--a', '-1', '--b', '{}'],
  ['--a', 'x', '--a', '{"a":1}', '--b', '{}'],
  ['--a', '1', '--b', '{}', '--', 'pos1'],
  ['--a', '1', '--b', '{}', '--x'],
  ['--a', '1', '--b', '{}', '-z'],
  ['--a', '-', '--b', '{}'],
];

let failures = 0;
for (const argv of cases) {
  const ref = spawnSync('/workspace/dataset/test20_executable', argv, { encoding: 'utf8' });
  const mine = spawnSync('node', ['/tmp/stub/test20.mjs', ...argv], { encoding: 'utf8' });

  // Reference stderr always starts with a DeprecationWarning we don't emit.
  const refStderr = ref.stderr.split('\n').filter((l) => !l.includes('DeprecationWarning') && !l.includes('will become')).join('\n').replace(/\[PYI.*\n?/g, '');
  // For crash cases the tracebacks differ; only compare argparse-level results.
  const isArgparseCase = ref.status === 2 || argv.includes('-h') || argv.includes('--he') || argv.includes('--h') || argv.includes('--help');

  if (isArgparseCase) {
    const ok = ref.status === mine.status && ref.stdout === mine.stdout && refStderr === mine.stderr;
    if (!ok) {
      failures += 1;
      console.log(`MISMATCH argv=${JSON.stringify(argv)}`);
      console.log(`  ref:  status=${ref.status} stdout=${JSON.stringify(ref.stdout)} stderr=${JSON.stringify(refStderr)}`);
      console.log(`  mine: status=${mine.status} stdout=${JSON.stringify(mine.stdout)} stderr=${JSON.stringify(mine.stderr)}`);
    }
  } else {
    // Only compare exit status class and stdout non-emptiness shape.
    if (ref.stdout !== mine.stdout && ref.status === 0 && mine.status === 0) {
      console.log(`note (full-run diff, may be stub-related): argv=${JSON.stringify(argv)}`);
    }
    if ((ref.status === 0) !== (mine.status === 0)) {
      failures += 1;
      console.log(`STATUS MISMATCH argv=${JSON.stringify(argv)}: ref=${ref.status} mine=${mine.status}`);
    }
  }
}
console.log(failures === 0 ? 'ALL ARG CASES MATCH' : `${failures} FAILURES`);

