import { Draft4Validator, Draft6Validator, Draft7Validator, Draft201909Validator, Draft202012Validator } from '/output/lib/drafts.mjs';
import { execFileSync } from 'node:child_process';

const VS = [Draft4Validator, Draft6Validator, Draft7Validator, Draft201909Validator, Draft202012Validator];

const cases = [
  ['1', '{"type":"integer"}'],
  ['"x"', '{"$ref": "#/definitions/n", "type": "integer", "definitions": {"n": {"type": "number"}}}'],
  ['"x"', '{"$ref": "#/$defs/n", "$defs": {"n": {"type": "number"}}}'],
  ['[1,2]', '{"items": {"$ref": "#"}, "minItems": 1}'],
  ['[[1],[]]', '{"items": {"$ref": "#"}, "minItems": 1}'],
  ['{"a":1}', '{"properties": {"a": false}}'],
  ['{"a":1}', '{"properties": {"a": true}}'],
  ['1', '{"bogusKw": 5}'],
  ['{"a":{"b":"x"}}', '{"properties":{"a":{"$ref":"#/definitions/inner"}},"definitions":{"inner":{"properties":{"b":{"$ref":"#/definitions/str"}},"str":{"type":"string"}}}}'],
  ['5', '{"minimum": 3, "maximum": 4}'],
  ['"aaa"', '{"minLength": 5}'],
  ['[1,2,3]', '{"prefixItems": [{"type":"string"}], "items": {"type":"integer"}}'],
  ['[1,"x"]', '{"prefixItems": [{"type":"string"}], "items": {"type":"integer"}}'],
  ['{"a":1,"b":2}', '{"required": ["a","c"], "additionalProperties": false}'],
  ['1', '{"allOf": [{"type":"string"},{"minimum":2}], "anyOf": [{"type":"string"},{"type":"boolean"}], "oneOf": [{"type":"number"},{"minimum":0}], "not": {"type":"integer"}}'],
  ['1', '{"if": {"type":"integer"}, "then": {"minimum": 5}, "else": {"type":"string"}}'],
  ['"x"', '{"if": {"type":"integer"}, "then": {"minimum": 5}, "else": {"type":"string"}}'],
  ['[1,1]', '{"uniqueItems": true}'],
  ['[1,true]', '{"uniqueItems": true}'],
  ['1.0', '{"type": "integer"}'],
  ['true', '{"type": "integer"}'],
  ['{"a":1}', '{"dependencies": {"a": ["b","c"]}}'],
  ['{"a":1}', '{"dependentRequired": {"a": ["b"]}}'],
  ['[1]', '{"contains": {"type":"string"}}'],
  ['[1]', '{"minContains": 2, "contains": {"type":"number"}}'],
  ['1', '{"const": 2}'],
  ['1', '{"enum": [1.0, "x"]}'],
  ['true', '{"enum": [1]}'],
  ['1', '{"multipleOf": 0.5}'],
  ['0.3', '{"multipleOf": 0.1}'],
  ['1', '{"pattern": "^a"}'],
  ['"abc"', '{"pattern": "b"}'],
  ['{"a":1}', '{"propertyNames": {"minLength": 3}}'],
  ['{"a":1,"extra":2}', '{"properties": {"a": {}}, "unevaluatedProperties": false}'],
  ['1', '{"prefixItems": [5]}'],
  ['1', '{"properties": {"a": 5}}'],
  ['1', '{"minimum": "x"}'],
  ['1', '{"$ref": "#/definitions/missing"}'],
  ['1', '{"$ref": "#"}'],
  ['1', '{"type": "bogus"}'],
  ['{"a": {"b": 1}}', '{"$ref": "#/definitions/rec", "definitions": {"rec": {"properties": {"b": {"type": "integer"}}}}}'],
  ['1', '{"$id": "https://ex.com/root", "$defs": {"n": {"$id": "other", "type": "integer"}}, "$ref": "other"}'],
  ['"s"', '{"$id": "https://ex.com/root", "$defs": {"n": {"$id": "other", "type": "integer"}}, "$ref": "other"}'],
  ['1', '{"minimum": 0, "exclusiveMinimum": true}'],
  ['0', '{"minimum": 0, "exclusiveMinimum": true}'],
  ['0', '{"exclusiveMinimum": 0}'],
  ['0.5', '{"exclusiveMinimum": 0}'],
];

let pass = 0, fail = 0;
for (const [a, b] of cases) {
  // reference
  let ref;
  try {
    const out = execFileSync('/workspace/dataset/test20_executable', ['--a', a, '--b', b], { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] });
    const lines = out.trim().split('\n');
    ref = {
      valid: lines.slice(0, 5).map(x => x === 'True'),
      counts: lines.slice(5, 10).map(Number),
      checks: lines.slice(10, 15),
    };
  } catch {
    ref = 'CRASH';
  }

  // ours
  let mine;
  try {
    const valid = [], counts = [], checks = [];
    for (const V of VS) {
      const v = new V(JSON.parse(b));
      const inst = JSON.parse(a);
      valid.push(v.isValid(inst));
      counts.push(v.iterErrors(inst).length);
      try { v.checkSchema(JSON.parse(b)); checks.push('None'); }
      catch { checks.push('CRASH'); }
    }
    // Python: any crash anywhere kills the whole run
    mine = checks.includes('CRASH') ? 'CRASH' : { valid, counts, checks };
  } catch {
    mine = 'CRASH';
  }

  const ok = JSON.stringify(ref) === JSON.stringify(mine);
  if (ok) pass++;
  else {
    fail++;
    console.log(`MISMATCH a=${a} b=${b}`);
    console.log('  ref :', JSON.stringify(ref));
    console.log('  mine:', JSON.stringify(mine));
  }
}
console.log(`pass=${pass} fail=${fail}`);

