// Scratch end-to-end test: run /output/test20.mjs vs the reference executable.
import { spawnSync } from 'node:child_process';

const cases = [
  ['{"a":1}', '{"type":"object"}'],
  ['1', '{"type":"string"}'],
  ['"abc"', '{"minLength": 5}'],
  ['{"a":{"b":"x"},"c":[1,2]}', '{"properties":{"a":{"properties":{"b":{"type":"integer"}}},"c":{"items":{"type":"string"}}}}'],
