  ['[1,2,2]', '{"uniqueItems": true}'],
  ['[1,2,3]', '{"uniqueItems": true}'],
  ['{"a":1,"b":2}', '{"required": ["a","c","d"]}'],
  ['{"a":1,"extra":true}', '{"properties":{"a":{}},"additionalProperties": false}'],
  ['15', '{"enum": [1, "x", [1,2], {"k": 1.0}]}'],
  ['1', '{"$schema": "http://json-schema.org/draft-04/schema#"}'],
  ['1', '{"$schema": "http://json-schema.org/draft-07/schema"}'],
  ['1', '{"$schema": "https://json-schema.org/draft/2019-09/schema"}'],
  ['1', '{"$schema": "HTTPS://json-schema.org/draft/2019-09/schema"}'],
  ['1', '{"$schema": "bogus"}'],
  ['1', '{"$schema": 5}'],
