  ['"2020-01-01"', '{"format": "date"}'],
  ['1', '{"allOf": [{"type":"string"},{"minimum": 5}]}'],
  ['1', '{"oneOf": [{"type":"number"},{"minimum": 0}]}'],
  ['"x"', '{"anyOf": [{"type":"number"},{"minLength": 5}]}'],
  ['1', '{"not": {"type": "integer"}}'],
  ['{"a":1}', '{"if": {"required":["a"]}, "then": {"required":["b"]}, "else": {"required":["c"]}}'],
  ['1', '{"$ref": "#/definitions/x", "definitions": {"x": {"type": "string"}}}'],
  ['[1,"a",true]', '{"items": [{"type":"number"},{"type":"string"}]}'],
  ['[1,"a",true]', '{"prefixItems": [{"type":"number"},{"type":"string"}], "items": {"type":"boolean"}}'],
  ['[1,2]', '{"contains": {"type": "string"}}'],
