  ['7', '{"multipleOf": 2.5}'],
  ['null', '{"const": null}'],
  ['1', '{"const": 1.0}'],
];

let failures = 0;
for (const [a, b] of cases) {
  const ref = spawnSync('/workspace/dataset/test20_executable', ['--a', a, '--b', b], { encoding: 'utf8' });
  const mine = spawnSync('node', ['/output/test20.mjs', '--a', a, '--b', b], { encoding: 'utf8' });
  const refOk = ref.status === 0;
  const mineOk = mine.status === 0;
  if (refOk !== mineOk || (refOk && ref.stdout !== mine.stdout)) {
    failures += 1;
    console.log(`MISMATCH a=${a} b=${b}`);
    console.log(`  ref:  status=${ref.status}\n${ref.stdout.split('\n').map(l => '    |' + l).join('\n')}`);
    console.log(`  mine: status=${mine.status}\n${mine.stdout.split('\n').map(l => '    |' + l).join('\n')}`);
  }
}
console.log(failures === 0 ? `ALL ${cases.length} END-TO-END CASES MATCH` : `${failures} FAILURES`);

